// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.memory.implimport com.roshan.persona.brain.context.SessionIdimport com.roshan.persona.brain.rule.storage.StateFileStorageimport com.roshan.persona.database.dao.ConversationStateDaoimport com.roshan.persona.database.entity.ConversationStateEntityimport timber.log.Timber/** * NOUS — Room-backed State File Storage. * * Implements [StateFileStorage] using Room's [ConversationStateDao]. * Persists conversation state across app restarts (Strategy §3.6). * * Each session's state is stored as a row in the conversation_states table. * The state data is serialized as a JSON string by CrashSafeConversationStateStorage * and passed to [write] as the `data` parameter. */class RoomStateFileStorage(    private val dao: ConversationStateDao,) : StateFileStorage {    override suspend fun write(sessionId: SessionId, data: String) {        try {            val now = System.currentTimeMillis()            val entity = ConversationStateEntity(                sessionId = sessionId.value,                correlationId = "",                skillId = "",                intent = "STATE_FILE",                stage = "",                partialOutput = data,                createdAt = now,                expiresAt = now + STATE_TTL_MS,            )            dao.upsert(entity)        } catch (e: Exception) {            Timber.e(e, "Failed to write state for session ${sessionId.value}")        }    }    override suspend fun read(sessionId: SessionId): String? {        return try {            val now = System.currentTimeMillis()            val entity = dao.getActiveForSession(sessionId.value, now)            entity?.partialOutput        } catch (e: Exception) {            Timber.e(e, "Failed to read state for session ${sessionId.value}")            null        }    }    override suspend fun delete(sessionId: SessionId) {        try {            dao.deleteForSession(sessionId.value)        } catch (e: Exception) {            Timber.e(e, "Failed to delete state for session ${sessionId.value}")        }    }    override suspend fun listAll(): List<SessionId> {        return try {            dao.getAllSessions().map { SessionId(it) }        } catch (e: Exception) {            Timber.e(e, "Failed to list all state sessions")            emptyList()        }    }    companion object {        private const val STATE_TTL_MS = 5 * 60 * 1000L  // 5 minutes    }}